/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable react-hooks/set-state-in-effect */
"use client";

import { useEffect, useState } from "react";
import { Globe, Check } from "lucide-react";

const languages = [
    { code: "en", name: "English", flag: "🇬🇧" },
    { code: "hi", name: "हिंदी", flag: "🇮🇳" },
    { code: "ml", name: "മലയാളം", flag: "🇮🇳" },
];

export default function Translator() {
    const [isOpen, setIsOpen] = useState(false);
    const [currentLang, setCurrentLang] = useState<string | null>(null);

    useEffect(() => {
        const savedLang = localStorage.getItem("forgive-lang");
        if (savedLang) {
            setCurrentLang(savedLang);
        } else {
            setCurrentLang(null); // NULL means it will show the mandatory picker
        }
    }, []);

    useEffect(() => {
        // Add Google Translate script if it doesn't exist
        if (!document.getElementById("google-translate-script")) {
            const script = document.createElement("script");
            script.id = "google-translate-script";
            script.src = "//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit";
            script.async = true;
            document.body.appendChild(script);

            // Define callback globally
            (window as any).googleTranslateElementInit = () => {
                new (window as any).google.translate.TranslateElement(
                    {
                        pageLanguage: "en",
                        includedLanguages: "en,hi,ml",
                        layout: (window as any).google.translate.TranslateElement.InlineLayout.SIMPLE,
                        autoDisplay: false
                    },
                    "google_translate_element"
                );
            };
        }

        // Hide Google's default floating bars completely and any body injected UI
        const styleId = "google-translate-hide-styles";
        if (!document.getElementById(styleId)) {
            const style = document.createElement("style");
            style.id = styleId;
            style.innerHTML = `
        /* Hide the top banner */
        .goog-te-banner-frame.skiptranslate, .goog-te-banner-frame { display: none !important; }
        
        /* Force body to stay at top and ignore Google translation body styling */
        body { top: 0px !important; position: static !important; }
        
        /* Hide the new translation wrapper class user mentioned */
        .VIpgJd-ZVi9od-ORHb-OEVmcd, .VIpgJd-ZVi9od-ORHb { display: none !important; }
        
        /* Hide tooltips and default widgets */
        #goog-gt-tt, .goog-te-balloon-frame { display: none !important; }
        .goog-tooltip, .goog-tooltip:hover { display: none !important; }
        .goog-text-highlight { background-color: transparent !important; border: none !important; box-shadow: none !important; }
        
        /* Hide the google combo box completely since we use custom UI */
        #google_translate_element { display: none !important; }
        .skiptranslate { display: none !important; }
        body > .skiptranslate { display: none !important; }
      `;
            document.head.appendChild(style);
        }
    }, []);

    // Programmatically trigger the hidden Google Translate combo box
    const changeLanguage = (langCode: string) => {
        const selectElement = document.querySelector(".goog-te-combo") as HTMLSelectElement;
        if (selectElement) {
            selectElement.value = langCode;
            selectElement.dispatchEvent(new Event("change", { bubbles: true }));
        }

        localStorage.setItem("forgive-lang", langCode);
        setCurrentLang(langCode);
        setIsOpen(false);
    };

    // Wait for hydration
    if (currentLang === null) {
        return (
            <>
                {/* Hidden google element just to mount the script target */}
                <div id="google_translate_element" className="hidden"></div>

                {/* Mandatory Language Overlay */}
                <div className="fixed inset-0 bg-[var(--background)] z-[100] flex flex-col items-center justify-center p-6 text-center">
                    <Globe size={48} className="text-[var(--primary)] mb-6" />
                    <h1 className="text-3xl font-light text-[var(--foreground)] mb-2">Welcome</h1>
                    <p className="text-[var(--nav-inactive)] mb-10 max-w-[280px]">
                        Please select your preferred language to continue.
                    </p>

                    <div className="w-full max-w-xs bg-white p-4 rounded-2xl shadow-lg border border-[var(--accent)] flex flex-col gap-2">
                        {languages.map((lang) => (
                            <button
                                key={lang.code}
                                onClick={() => changeLanguage(lang.code)}
                                className="flex items-center gap-3 w-full p-4 rounded-xl border border-[var(--accent)] bg-[var(--nav-bg)] hover:bg-[var(--accent)]/30 transition-colors text-left"
                            >
                                <span className="text-2xl">{lang.flag}</span>
                                <span className="text-base font-medium text-[var(--foreground)] flex-1">{lang.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </>
        );
    }

    return (
        <>
            {/* Hidden google element just to mount the script target */}
            <div id="google_translate_element" className="hidden"></div>

            {/* Normal Top Right Button */}
            <div className="absolute top-6 right-6 z-50">
                <button
                    onClick={() => setIsOpen(!isOpen)}
                    className="w-10 h-10 bg-white shadow-sm border border-[var(--accent)] rounded-full flex items-center justify-center text-[var(--nav-inactive)] hover:text-[var(--foreground)] transition-colors"
                >
                    <Globe size={18} />
                </button>

                {isOpen && (
                    <div className="absolute top-12 right-0 bg-white p-4 pb-14 rounded-xl shadow-lg border border-[var(--accent)] min-w-[220px] flex flex-col items-center gap-2">
                        <span className="text-xs text-[var(--nav-inactive)] mb-2 w-full text-left font-medium">Select Language</span>

                        {languages.map((lang) => {
                            const isActive = currentLang === lang.code;
                            return (
                                <button
                                    key={lang.code}
                                    onClick={() => changeLanguage(lang.code)}
                                    className={\`flex items-center gap-3 w-full py-2 px-3 rounded-lg transition-colors text-left \${
                            isActive ? "bg-[var(--primary)]/10 border border-[var(--primary)]/20" : "hover:bg-[var(--accent)]/50 border border-transparent"
                        }\`}
                  >
                        <span className="text-xl leading-none">{lang.flag}</span>
                        <span className={\`text-sm font-medium flex-1 \${isActive ? "text-[var(--primary-dark)]" : "text-[var(--foreground)]"}\`}>
                        {lang.name}
                    </span>
                    {isActive && <Check size={16} className="text-[var(--primary-dark)]" />}
            </button>
            )
              })}

            <button
                onClick={() => setIsOpen(false)}
                className="absolute bottom-4 text-xs text-[var(--nav-inactive)] hover:text-[var(--foreground)]"
            >
                Close
            </button>
        </div >
        )
}
      </div >
    </>
  );
}
